import click
from click.testing import CliRunner
import pytest

class MyClass:
    def __init__(self, value: str):
        self.value = value

    @staticmethod
    def from_str(input_str: str) -> "MyClass":
        if input_str != "works":
            raise ValueError(f"input was {input_str=}, should be works")
        return MyClass(input_str)


@click.command()
@click.argument("mydata", type=click.FuncParamType(MyClass.from_str))
def cli(mydata):
    click.echo(f"Success: {mydata.value}")

